-- Portable SQL: runs on SQLite (dev) and Postgres (hosting).
-- IDs are TEXT UUIDs generated by the app; timestamps are ISO-8601 TEXT; dates are YYYY-MM-DD.

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  role TEXT NOT NULL CHECK (role IN ('learner', 'tech_evaluator', 'sales', 'manager')),
  title TEXT,
  password_hash TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL
);

CREATE TABLE enrollments (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  start_date TEXT NOT NULL,
  primary_oem TEXT,
  tech_evaluator_id TEXT REFERENCES users(id),
  pitch_manager_id TEXT REFERENCES users(id),
  pitch_sales_id TEXT REFERENCES users(id),
  gating_override INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE step_progress (
  enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
  module_id TEXT NOT NULL,
  step_id TEXT NOT NULL,
  completed_at TEXT NOT NULL,
  PRIMARY KEY (enrollment_id, module_id, step_id)
);

CREATE TABLE task_progress (
  enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
  task_id TEXT NOT NULL,
  status TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (enrollment_id, task_id)
);

CREATE TABLE evidence (
  id TEXT PRIMARY KEY,
  enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
  module_id TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('notes', 'screenshot', 'config', 'recording_link')),
  title TEXT,
  content TEXT,
  file_ref TEXT,
  file_name TEXT,
  submitted_at TEXT NOT NULL
);
CREATE INDEX evidence_enrollment_module ON evidence (enrollment_id, module_id);

CREATE TABLE exit_proofs (
  enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
  module_id TEXT NOT NULL,
  submitted_at TEXT NOT NULL,
  PRIMARY KEY (enrollment_id, module_id)
);

CREATE TABLE checkpoint_attempts (
  id TEXT PRIMARY KEY,
  enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
  checkpoint_id TEXT NOT NULL,
  attempt_number INTEGER NOT NULL,
  scheduled_date TEXT,
  evaluator_id TEXT REFERENCES users(id),
  status TEXT NOT NULL CHECK (status IN ('scheduled', 'passed', 'needs_work')),
  notes TEXT,
  retake_window_end TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL,
  UNIQUE (enrollment_id, checkpoint_id, attempt_number)
);

CREATE TABLE checkpoint_module_results (
  attempt_id TEXT NOT NULL REFERENCES checkpoint_attempts(id) ON DELETE CASCADE,
  module_id TEXT NOT NULL,
  result TEXT NOT NULL CHECK (result IN ('pass', 'needs_work')),
  notes TEXT,
  PRIMARY KEY (attempt_id, module_id)
);

CREATE TABLE scenarios (
  enrollment_id TEXT PRIMARY KEY REFERENCES enrollments(id) ON DELETE CASCADE,
  vertical TEXT NOT NULL,
  company TEXT NOT NULL,
  company_profile TEXT,
  contact_name TEXT NOT NULL,
  contact_title TEXT,
  contact_profile TEXT,
  met_at TEXT,
  research TEXT NOT NULL DEFAULT '{}',
  priority_restatement TEXT,
  discovery TEXT NOT NULL DEFAULT '[]',
  pitch_plan TEXT NOT NULL DEFAULT '{}',
  assigned_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE pitch_sessions (
  id TEXT PRIMARY KEY,
  enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
  stage TEXT NOT NULL CHECK (stage IN ('baseline', 'coaching', 'practice', 'graded', 'retake_coaching', 'retake')),
  attempt_number INTEGER NOT NULL DEFAULT 1,
  session_date TEXT,
  manager_evaluator_id TEXT REFERENCES users(id),
  sales_evaluator_id TEXT REFERENCES users(id),
  status TEXT NOT NULL CHECK (status IN ('scheduled', 'completed')),
  scores TEXT,
  total INTEGER,
  feedback TEXT,
  observations TEXT,
  focus_dimensions TEXT,
  retake_window_end TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX pitch_sessions_enrollment ON pitch_sessions (enrollment_id);
